import { fileURLToPath, URL } from 'node:url'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { defineConfig } from 'vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  server: {
    port: 5173,
  },
})

{
  "compilerOptions": {
    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.app.tsbuildinfo",
    "target": "es2023",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "module": "esnext",
    "types": ["vite/client"],
    "allowArbitraryExtensions": true,
    "skipLibCheck": true,

    /* Bundler mode */
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "verbatimModuleSyntax": true,
    "moduleDetection": "force",
    "noEmit": true,
    "jsx": "react-jsx",

    /* Path aliases */
    "baseUrl": ".",
    "paths": {
      "@/*": ["./src/*"]
    },

    /* Type safety */
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "erasableSyntaxOnly": true,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["src"]
}

@import 'tailwindcss';

@theme {
  --font-sans:
    'Inter Variable', ui-sans-serif, system-ui, -apple-system, 'Segoe UI',
    sans-serif;

  --color-brand-50: #f2f7fb;
  --color-brand-100: #e4eef7;
  --color-brand-200: #c6dcee;
  --color-brand-300: #9bc1e0;
  --color-brand-400: #68a0cd;
  --color-brand-500: #4283b8;
  --color-brand-600: #2f699c;
  --color-brand-700: #28557e;
  --color-brand-800: #244969;
  --color-brand-900: #133a5c;
  --color-brand-950: #0a2239;

  --shadow-panel:
    0 1px 2px rgb(15 23 42 / 0.04), 0 12px 32px -20px rgb(15 23 42 / 0.18);
  --shadow-raised:
    0 1px 2px rgb(15 23 42 / 0.06), 0 8px 20px -12px rgb(15 23 42 / 0.22);

  --animate-fade-in: fade-in 180ms ease-out;
  --animate-rise: rise 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-slate-100 font-sans text-slate-700 antialiased;
  }

  ::selection {
    @apply bg-brand-200 text-brand-950;
  }

  :focus-visible {
    @apply outline-2 outline-offset-2 outline-brand-500;
  }

  h1,
  h2,
  h3,
  h4 {
    @apply text-slate-900;
    text-wrap: balance;
  }

  button,
  a,
  input,
  select,
  textarea {
    -webkit-tap-highlight-color: transparent;
  }
}

@layer utilities {
  .bg-archive-grid {
    background-image:
      linear-gradient(to right, rgb(255 255 255 / 0.045) 1px, transparent 1px),
      linear-gradient(to bottom, rgb(255 255 255 / 0.045) 1px, transparent 1px);
    background-size: 44px 44px;
  }

  .scrollbar-slim {
    scrollbar-width: thin;
    scrollbar-color: var(--color-slate-300) transparent;
  }

  .scrollbar-slim::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  .scrollbar-slim::-webkit-scrollbar-thumb {
    background-color: var(--color-slate-300);
    border-radius: 9999px;
  }

  .scrollbar-dark {
    scrollbar-width: thin;
    scrollbar-color: rgb(255 255 255 / 0.16) transparent;
  }

  .scrollbar-dark::-webkit-scrollbar {
    width: 8px;
  }

  .scrollbar-dark::-webkit-scrollbar-thumb {
    background-color: rgb(255 255 255 / 0.16);
    border-radius: 9999px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

