import type { Session } from '@supabase/supabase-js'
import type { ReactNode } from 'react'
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react'
import { supabase, supabaseConfig } from '@/lib/supabase/client'
import type { AppRole } from '@/lib/supabase/database.types'
import type { StaffProfile } from '@/lib/roles'

export type AuthStatus =
  | 'unconfigured'
  | 'initializing'
  | 'signed_out'
  | 'loading_profile'
  | 'unprovisioned'
  | 'inactive'
  | 'error'
  | 'authenticated'

type ProfileState = 'idle' | 'loading' | 'ready' | 'missing' | 'error'

interface AuthContextValue {
  status: AuthStatus
  session: Session | null
  profile: StaffProfile | null
  profileError: string | null
  isConfigured: boolean
  isAdmin: boolean
  hasRole: (...roles: AppRole[]) => boolean
  signOut: () => Promise<void>
  refreshProfile: () => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null)
  const [sessionLoaded, setSessionLoaded] = useState(!supabase)
  const [profile, setProfile] = useState<StaffProfile | null>(null)
  const [profileState, setProfileState] = useState<ProfileState>('idle')
  const [profileError, setProfileError] = useState<string | null>(null)
  const [profileReloadToken, setProfileReloadToken] = useState(0)

  useEffect(() => {
    if (!supabase) return

    let active = true

    supabase.auth
      .getSession()
      .then(({ data, error }) => {
        if (!active) return
        if (error) {
          console.error('Unable to restore the TRACE session:', error.message)
        }
        setSession(data.session)
        setSessionLoaded(true)
      })
      .catch((error: unknown) => {
        if (!active) return
        console.error('Unable to restore the TRACE session:', error)
        setSessionLoaded(true)
      })

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, nextSession) => {
      setSession(nextSession)
      setSessionLoaded(true)

      if (!nextSession) {
        setProfile(null)
        setProfileState('idle')
        setProfileError(null)
      }
    })

    return () => {
      active = false
      subscription.unsubscribe()
    }
  }, [])

  const userId = session?.user.id

  useEffect(() => {
    if (!supabase || !userId) {
      setProfile(null)
      setProfileState('idle')
      setProfileError(null)
      return
    }

    let active = true
    setProfile(null)
    setProfileState('loading')
    setProfileError(null)

    void supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .maybeSingle()
      .then(({ data, error }) => {
        if (!active) return

        if (error) {
          console.error('Unable to load the staff profile:', error.message)
          setProfileState('error')
          setProfileError(error.message)
          return
        }

        if (!data) {
          setProfileState('missing')
          return
        }

        setProfile(data)
        setProfileState('ready')
      })

    return () => {
      active = false
    }
  }, [userId, profileReloadToken])

  const signOut = useCallback(async () => {
    if (!supabase) return
    const { error } = await supabase.auth.signOut()
    if (error) throw new Error(error.message)
    setSession(null)
    setProfile(null)
    setProfileState('idle')
    setProfileError(null)
  }, [])

  const refreshProfile = useCallback(() => {
    setProfileReloadToken((token) => token + 1)
  }, [])

  const status: AuthStatus = useMemo(() => {
    if (!supabaseConfig.isConfigured) return 'unconfigured'
    if (!sessionLoaded) return 'initializing'
    if (!session) return 'signed_out'
    if (profileState === 'idle' || profileState === 'loading') {
      return 'loading_profile'
    }
    if (profileState === 'error') return 'error'
    if (profileState === 'missing') return 'unprovisioned'
    if (!profile?.is_active) return 'inactive'
    return 'authenticated'
  }, [sessionLoaded, session, profileState, profile])

  const hasRole = useCallback(
    (...roles: AppRole[]) =>
      Boolean(
        profile?.is_active &&
          roles.length > 0 &&
          roles.includes(profile.role),
      ),
    [profile],
  )

  const value = useMemo<AuthContextValue>(
    () => ({
      status,
      session,
      profile,
      profileError,
      isConfigured: supabaseConfig.isConfigured,
      isAdmin: Boolean(profile?.is_active && profile.role === 'administrator'),
      hasRole,
      signOut,
      refreshProfile,
    }),
    [status, session, profile, profileError, hasRole, signOut, refreshProfile],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth(): AuthContextValue {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

import { useState } from 'react'
import { LogOut, RefreshCw, ShieldAlert } from 'lucide-react'
import { toast } from 'sonner'
import { Alert } from '@/components/ui/Alert'
import { Button } from '@/components/ui/Button'
import { useAuth } from '@/context/AuthContext'

export function AccessBlocked() {
  const { status, session, profileError, refreshProfile, signOut } = useAuth()
  const [isSigningOut, setIsSigningOut] = useState(false)

  const email = session?.user.email ?? 'your account'

  const copy =
    status === 'unprovisioned'
      ? {
          title: 'No staff profile found',
          description: `TRACE authenticated ${email}, but there is no staff profile linked to this account. An administrator must provision your profile before you can access archival records.`,
        }
      : status === 'inactive'
        ? {
            title: 'Account not activated',
            description: `The staff profile for ${email} exists but is inactive. Contact the Registrar administrator to restore access.`,
          }
        : {
            title: 'Access could not be verified',
            description:
              'TRACE could not load your staff profile. This usually means the database migration has not been applied, or the connection was interrupted.',
          }

  async function handleSignOut() {
    setIsSigningOut(true)
    try {
      await signOut()
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : 'Unable to sign out.',
      )
      setIsSigningOut(false)
    }
  }

  return (
    <div className="flex min-h-svh items-center justify-center bg-slate-100 px-4 py-10">
      <div className="w-full max-w-lg animate-rise">
        <div className="mb-6 flex items-center justify-center gap-2.5">
          <span className="flex size-9 items-center justify-center rounded-lg bg-brand-950 text-white">
            <ShieldAlert className="size-4" aria-hidden="true" />
          </span>
          <span className="text-sm font-semibold tracking-[0.2em] text-brand-950">
            TRACE
          </span>
        </div>

        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-panel sm:p-8">
          <h1 className="text-xl font-semibold tracking-tight text-slate-900">
            {copy.title}
          </h1>
          <p className="mt-2 text-sm leading-relaxed text-slate-600">
            {copy.description}
          </p>

          {status === 'error' && profileError ? (
            <Alert variant="danger" title="Database response" className="mt-5">
              <code className="block break-words text-xs leading-relaxed">
                {profileError}
              </code>
            </Alert>
          ) : null}

          <div className="mt-6 space-y-3">
            {status === 'error' ? (
              <Button
                onClick={refreshProfile}
                leftIcon={<RefreshCw className="size-4" />}
                className="w-full"
              >
                Retry verification
              </Button>
            ) : null}

            <Button
              variant={status === 'error' ? 'secondary' : 'primary'}
              onClick={handleSignOut}
              isLoading={isSigningOut}
              leftIcon={<LogOut className="size-4" />}
              className="w-full"
            >
              Sign out
            </Button>
          </div>

          <p className="mt-6 border-t border-slate-200 pt-5 text-xs leading-relaxed text-slate-500">
            Account provisioning and role assignment are performed by an
            authorized TRACE administrator. Access to student records is
            logged and limited to Registrar personnel.
          </p>
        </div>

        <p className="mt-5 text-center text-xs text-slate-400">
          Junior High School Registrar&apos;s Office ┬╖ Internal system
        </p>
      </div>
    </div>
  )
}

import { Navigate, Outlet, useLocation } from 'react-router-dom'
import { AccessBlocked } from '@/components/auth/AccessBlocked'
import { FullPageLoader } from '@/components/ui/Spinner'
import { useAuth } from '@/context/AuthContext'

/**
 * Gate for every internal route. It waits for the session and the staff
 * profile, redirects unauthenticated visitors, and refuses access for
 * accounts that are unprovisioned or inactive.
 *
 * This is a usability boundary. The authoritative controls are the
 * PostgreSQL row-level security policies in the Supabase project.
 */
export function ProtectedRoute() {
  const { status } = useAuth()
  const location = useLocation()

  if (status === 'unconfigured' || status === 'signed_out') {
    return (
      <Navigate
        to="/login"
        replace
        state={{ from: `${location.pathname}${location.search}` }}
      />
    )
  }

  if (status === 'initializing' || status === 'loading_profile') {
    return <FullPageLoader />
  }

  if (
    status === 'unprovisioned' ||
    status === 'inactive' ||
    status === 'error'
  ) {
    return <AccessBlocked />
  }

  return <Outlet />
}

import { Navigate, Outlet } from 'react-router-dom'
import { useAuth } from '@/context/AuthContext'
import type { AppRole } from '@/lib/supabase/database.types'

/**
 * Hides administrator-only screens from other roles. The same restriction
 * must exist in RLS; this component is navigation hygiene, not security.
 */
export function RequireRole({ roles }: { roles: AppRole[] }) {
  const { profile } = useAuth()

  if (!profile || !profile.is_active || !roles.includes(profile.role)) {
    return <Navigate to="/403" replace />
  }

  return <Outlet />
}

