import { useEffect, useMemo, useRef, useState } from 'react'
import {
  CornerDownLeft,
  LogOut,
  Search,
  SearchX,
  UserRound,
} from 'lucide-react'
import { createPortal } from 'react-dom'
import { useNavigate } from 'react-router-dom'
import { toast } from 'sonner'
import { Kbd } from '@/components/ui/Kbd'
import { useAuth } from '@/context/AuthContext'
import { getModuleByPath } from '@/lib/modules'
import {
  ACCOUNT_NAV_ITEM,
  canAccessNavItem,
  NAV_SECTIONS,
} from '@/lib/navigation'
import { cn } from '@/lib/utils'
import type { LucideIcon } from 'lucide-react'

interface PaletteEntry {
  id: string
  label: string
  section: string
  icon: LucideIcon
  keywords: string[]
  to?: string
  action?: 'sign_out'
  meta: string
}

interface CommandPaletteProps {
  open: boolean
  onClose: () => void
}

export function CommandPalette({ open, onClose }: CommandPaletteProps) {
  const { profile, signOut } = useAuth()
  const navigate = useNavigate()
  const [query, setQuery] = useState('')
  const [activeIndex, setActiveIndex] = useState(0)
  const [isSigningOut, setIsSigningOut] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const entries = useMemo<PaletteEntry[]>(() => {
    const items: PaletteEntry[] = NAV_SECTIONS.flatMap((section) =>
      section.items
        .filter((item) => canAccessNavItem(item, profile?.role))
        .map((item) => {
          const module = getModuleByPath(item.to)
          return {
            id: item.to,
            label: item.label,
            section: section.label,
            icon: item.icon,
            keywords: item.keywords ?? [],
            to: item.to,
            meta: module ? `Phase ${module.phase}` : 'Module',
          }
        }),
    )

    items.push({
      id: ACCOUNT_NAV_ITEM.to,
      label: ACCOUNT_NAV_ITEM.label,
      section: 'Account',
      icon: UserRound,
      keywords: ACCOUNT_NAV_ITEM.keywords ?? [],
      to: ACCOUNT_NAV_ITEM.to,
      meta: 'Profile',
    })

    items.push({
      id: 'sign-out',
      label: 'Sign out of TRACE',
      section: 'Session',
      icon: LogOut,
      keywords: ['logout', 'exit', 'sign out'],
      action: 'sign_out',
      meta: 'Security',
    })

    return items
  }, [profile?.role])

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase()
    if (!term) return entries
    return entries.filter((entry) =>
      [entry.label, entry.section, entry.meta, ...entry.keywords]
        .join(' ')
        .toLowerCase()
        .includes(term),
    )
  }, [entries, query])

  useEffect(() => {
    if (!open) return
    setQuery('')
    setActiveIndex(0)
    const frame = window.requestAnimationFrame(() => inputRef.current?.focus())
    return () => window.cancelAnimationFrame(frame)
  }, [open])

  useEffect(() => {
    if (!open) return
    const previous = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = previous
    }
  }, [open])

  useEffect(() => {
    if (!open) return
    const element = document.getElementById(`palette-option-${activeIndex}`)
    element?.scrollIntoView({ block: 'nearest' })
  }, [activeIndex, open])

  useEffect(() => {
    setActiveIndex(0)
  }, [query])

  if (!open) return null

  async function selectEntry(entry: PaletteEntry | undefined) {
    if (!entry) return

    if (entry.action === 'sign_out') {
      setIsSigningOut(true)
      try {
        await signOut()
        toast.success('You have been signed out.')
        onClose()
        navigate('/login', { replace: true })
      } catch (error) {
        toast.error(
          error instanceof Error ? error.message : 'Unable to sign out.',
        )
        setIsSigningOut(false)
      }
      return
    }

    if (entry.to) {
      navigate(entry.to)
      onClose()
    }
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      if (filtered.length === 0) return
      setActiveIndex((index) => (index + 1) % filtered.length)
      return
    }

    if (event.key === 'ArrowUp') {
      event.preventDefault()
      if (filtered.length === 0) return
      setActiveIndex(
        (index) => (index - 1 + filtered.length) % filtered.length,
      )
      return
    }

    if (event.key === 'Enter') {
      event.preventDefault()
      if (!isSigningOut) void selectEntry(filtered[activeIndex])
      return
    }

    if (event.key === 'Escape') {
      event.preventDefault()
      onClose()
    }
  }

  return createPortal(
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-slate-950/50 px-4 pt-[10vh] pb-8 backdrop-blur-[2px] animate-fade-in"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose()
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label="TRACE command palette"
        className="w-full max-w-xl animate-rise overflow-hidden rounded-xl border border-slate-200 bg-white shadow-2xl"
      >
        <div className="flex items-center gap-3 border-b border-slate-200 px-4">
          <Search className="size-4 shrink-0 text-slate-400" aria-hidden="true" />
          <input
            ref={inputRef}
            type="text"
            role="combobox"
