const targets = await (await fetch('http://127.0.0.1:9223/json/list')).json()
const page = targets.find((target) => target.type === 'page')
if (!page) throw new Error('No page target')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true })
  ws.addEventListener('error', reject, { once: true })
})

let nextId = 0
function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId
    const onMessage = (event) => {
      const message = JSON.parse(event.data)
      if (message.id === id) {
        ws.removeEventListener('message', onMessage)
        if (message.error) reject(new Error(JSON.stringify(message.error)))
        else resolve(message.result)
      }
    }
    ws.addEventListener('message', onMessage)
    ws.send(JSON.stringify({ id, method, params }))
  })
}

await send('Runtime.enable')
const result = await send('Runtime.evaluate', {
  expression: `(() => {
    const all = [...document.querySelectorAll('*')].map((el) => {
      const r = el.getBoundingClientRect()
      return {
        tag: el.tagName,
        cls: String(el.className || '').slice(0, 70),
        width: Math.round(r.width),
        left: Math.round(r.left),
        right: Math.round(r.right),
        scrollWidth: el.scrollWidth,
      }
    })
    return JSON.stringify({
      innerWidth: window.innerWidth,
      outerWidth: window.outerWidth,
      devicePixelRatio: window.devicePixelRatio,
      docScrollWidth: document.documentElement.scrollWidth,
      bodyScrollWidth: document.body.scrollWidth,
      sections: [...document.querySelectorAll('section')].map((el) => {
        const r = el.getBoundingClientRect()
        return { width: Math.round(r.width), left: Math.round(r.left), right: Math.round(r.right) }
      }),
      wide: all.filter((item) => item.right > window.innerWidth + 1 || item.width > window.innerWidth + 1).slice(0, 12),
    }, null, 2)
  })()`,
  returnByValue: true,
})

