  }
}

function buildSession(account) {
  return {
    access_token: 'mock-access-token',
    token_type: 'bearer',
    expires_in: 3600,
    expires_at: 4102444800,
    refresh_token: 'mock-refresh-token',
    user: buildUser(account),
  }
}

const browser = await chromium.launch({
  executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
  headless: true,
})

async function makeContext(account, viewport = { width: 1440, height: 1000 }) {
  const context = await browser.newContext({ viewport })
  if (account) {
    await context.addInitScript((payload) => {
      try {
        localStorage.setItem('sb-demo-auth-token', JSON.stringify(payload))
      } catch {
        /* ignore */
      }
    }, buildSession(account))
  }

  await context.route('https://demo.supabase.co/**', async (route) => {
    const url = route.request().url()
    const headers = {
      'access-control-allow-origin': '*',
      'access-control-allow-headers': '*',
      'access-control-allow-methods': '*',
      'content-type': 'application/json',
    }
    const fulfill = (body, status = 200) =>
      route.fulfill({ status, headers, body: JSON.stringify(body) })

    if (url.includes('/auth/v1/user')) {
      if (!account) return fulfill({ message: 'invalid token' }, 401)
      return fulfill(buildUser(account))
    }
    if (url.includes('/auth/v1/token')) {
      if (!account) return fulfill({ error: 'invalid_grant' }, 400)
      return fulfill({ ...buildSession(account), access_token: 'mock-2' })
    }
    if (url.includes('/auth/v1/logout')) return fulfill({})
    if (url.includes('/rest/v1/system_settings')) {
      return fulfill({
        value: { version: '0.1.0', phase: 1 },
        updated_at: '2026-11-24T08:00:00Z',
      })
    }
    if (url.includes('/rest/v1/audit_logs')) {
      if (account?.role !== 'administrator') {
        return fulfill({ code: '42501', message: 'permission denied' }, 403)
      }
      return fulfill([
        {
          id: 2,
          actor_id: users.admin.id,
          actor_email: users.admin.email,
          action: 'auth.sign_in',
          entity_type: 'session',
          entity_id: users.admin.id,
          summary: 'Signed in to TRACE',
          metadata: { method: 'password' },
          created_at: '2026-11-24T13:42:00Z',
        },
      ])
    }
    if (url.includes('/rest/v1/profiles')) {
      if (!account) return fulfill({ code: '42501' }, 403)
      if (url.includes('select=id%2Cis_active') || url.includes('select=id,is_active')) {
        return fulfill([{ id: account.id, is_active: account.is_active }])
      }
      if (url.includes('head=true') || route.request().method() === 'HEAD') {
        return route.fulfill({ status: 200, headers, body: '' })
      }
      if (url.includes('id=eq.')) return fulfill(account)
      return fulfill([account])
    }
    return fulfill([])
  })

  return context
}

