// Read-only Phase 1 verification through PostgREST with the publishable key.
// No writes. Secrets are not printed.
import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync(new URL('./.env', import.meta.url), 'utf8')
    .split(/\r?\n/)
    .filter((line) => line && !line.startsWith('#') && line.includes('='))
    .map((line) => {
      const i = line.indexOf('=')
      return [line.slice(0, i).trim(), line.slice(i + 1).trim()]
    }),
)

const base = env.VITE_SUPABASE_URL
const key = env.VITE_SUPABASE_ANON_KEY
const headers = { apikey: key, Authorization: `Bearer ${key}` }

async function get(path, extra = {}) {
  const res = await fetch(`${base}${path}`, { headers: { ...headers, ...extra } })
  const text = await res.text()
  let body = null
  try {
    body = JSON.parse(text)
  } catch {
    body = text.slice(0, 400)
  }
  return { status: res.status, body }
}

console.log('PROJECT:', base.replace(/^https:\/\/([^.]+).*/, '$1'))

const spec = await get('/rest/v1/', { Accept: 'application/openapi+json' })
console.log('OPENAPI STATUS:', spec.status)

if (spec.status !== 200) {
  console.log('BODY:', JSON.stringify(spec.body).slice(0, 800))
  process.exit(0)
}

const doc = spec.body
const tables = Object.keys(doc.definitions ?? {})
const rpcs = Object.keys(doc.paths ?? {})
  .filter((p) => p.startsWith('/rpc/'))
  .map((p) => p.replace('/rpc/', ''))

console.log('TABLES:', tables.join(', ') || '(none)')
console.log('RPCS:', rpcs.join(', ') || '(none)')

for (const table of ['profiles', 'system_settings', 'audit_logs']) {
  const def = doc.definitions?.[table]
  console.log(
    `COLUMNS ${table}:`,
    def ? Object.keys(def.properties ?? {}).join(', ') : 'MISSING',
  )
}

const roleDef = doc.definitions?.app_role
console.log('ENUM app_role:', roleDef ? JSON.stringify(roleDef.enum) : 'not exposed')

console.log('')
console.log('--- anon read probes (RLS should deny) ---')
for (const table of ['profiles', 'system_settings', 'audit_logs']) {
  const res = await get(`/rest/v1/${table}?select=*&limit=1`)
  const detail = Array.isArray(res.body)
    ? `rows=${res.body.length}`
    : JSON.stringify(res.body).slice(0, 200)
  console.log(`${table}: HTTP ${res.status} ${detail}`)
