// Read-only Phase 1 verification through PostgREST with the publishable key.
// No writes. Secrets are not printed.
import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync(new URL('./.env', import.meta.url), 'utf8')
    .split(/\r?\n/)
    .filter((line) => line && !line.startsWith('#') && line.includes('='))
    .map((line) => {
      const i = line.indexOf('=')
      return [line.slice(0, i).trim(), line.slice(i + 1).trim()]
    }),
)

const base = env.VITE_SUPABASE_URL
const key = env.VITE_SUPABASE_ANON_KEY
const headers = { apikey: key, Authorization: `Bearer ${key}` }

async function req(method, path, body) {
  const res = await fetch(`${base}${path}`, {
    method,
    headers: body
      ? { ...headers, 'Content-Type': 'application/json' }
      : headers,
    body: body ? JSON.stringify(body) : undefined,
  })
  const text = await res.text()
  let parsed
  try {
    parsed = JSON.parse(text)
  } catch {
    parsed = text.slice(0, 300)
  }
  return { status: res.status, body: parsed }
}

function describe(res) {
  if (Array.isArray(res.body)) return `rows=${res.body.length}`
  const b = res.body
  if (b && typeof b === 'object') {
    return [b.code, b.message].filter(Boolean).join(' | ').slice(0, 160)
  }
  return String(b).slice(0, 160)
}

console.log('PROJECT:', base.replace(/^https:\/\/([^.]+).*/, '$1'))
console.log('')

console.log('--- table existence + anon RLS behaviour ---')
for (const table of [
  'profiles',
  'system_settings',
  'audit_logs',
  'students',
  'documents',
]) {
  const res = await req('GET', `/rest/v1/${table}?select=*&limit=1`)
  console.log(`${table.padEnd(16)} HTTP ${res.status}  ${describe(res)}`)
}

console.log('')
console.log('--- control: nonexistent table should 404 ---')
{
  const res = await req('GET', '/rest/v1/trace_phase1_absent?select=*&limit=1')
  console.log(`absent table     HTTP ${res.status}  ${describe(res)}`)
}

console.log('')
console.log('--- RPC existence ---')
for (const rpc of ['record_sign_in', 'record_audit_event', 'trace_absent_rpc']) {
  const res = await req('POST', `/rest/v1/rpc/${rpc}`, {})
  console.log(`${rpc.padEnd(20)} HTTP ${res.status}  ${describe(res)}`)
}

console.log('')
console.log('--- auth settings (public endpoint) ---')
{
  const res = await req('GET', '/auth/v1/settings')
  const b = res.body
  if (res.status === 200 && b && typeof b === 'object') {
    console.log('email auth enabled:', b.external?.email ?? 'unknown')
    console.log('signups disabled :', b.disable_signup ?? 'unknown')
    console.log('autoconfirm      :', b.mailer_autoconfirm ?? 'unknown')
  } else {
    console.log(`HTTP ${res.status} ${describe(res)}`)
  }
}

// Read-only column/signature verification. No writes, no account creation.
import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync(new URL('./.env', import.meta.url), 'utf8')
    .split(/\r?\n/)
    .filter((line) => line && !line.startsWith('#') && line.includes('='))
    .map((line) => {
      const i = line.indexOf('=')
      return [line.slice(0, i).trim(), line.slice(i + 1).trim()]
    }),
)

const base = env.VITE_SUPABASE_URL
const key = env.VITE_SUPABASE_ANON_KEY
const headers = { apikey: key, Authorization: `Bearer ${key}` }

async function req(method, path, body) {
  const res = await fetch(`${base}${path}`, {
    method,
    headers: body ? { ...headers, 'Content-Type': 'application/json' } : headers,
    body: body ? JSON.stringify(body) : undefined,
  })
  const text = await res.text()
  let parsed
  try {
    parsed = JSON.parse(text)
  } catch {
    parsed = text.slice(0, 200)
  }
  return { status: res.status, body: parsed }
}

function tag(res) {
  const b = res.body
  if (b && typeof b === 'object' && !Array.isArray(b)) {
    return `${b.code ?? ''} ${String(b.message ?? '').slice(0, 90)}`.trim()
  }
  return String(JSON.stringify(b)).slice(0, 90)
}

const expected = {
  profiles: ['id', 'email', 'full_name', 'role', 'is_active', 'created_at', 'updated_at'],
  system_settings: ['key', 'value', 'description', 'updated_at', 'updated_by'],
  audit_logs: [
    'id',
    'actor_id',
    'actor_email',
    'action',
    'entity_type',
    'entity_id',
    'summary',
    'metadata',
    'created_at',
  ],
}

console.log('--- column resolution (401 = columns valid but denied; PGRST204 = bad column) ---')
for (const [table, cols] of Object.entries(expected)) {
  const ok = await req('GET', `/rest/v1/${table}?select=${cols.join(',')}&limit=1`)
  const bogus = await req('GET', `/rest/v1/${table}?select=trace_bogus_column&limit=1`)
  console.log(
    `${table.padEnd(16)} real: HTTP ${ok.status} ${tag(ok)}\n${''.padEnd(18)}bogus: HTTP ${bogus.status} ${tag(bogus)}`,
  )
}

console.log('')
console.log('--- record_audit_event with full signature ---')
{
  const res = await req('POST', '/rest/v1/rpc/record_audit_event', {
    p_action: 'verification.probe',
    p_entity_type: 'verification',
    p_entity_id: null,
    p_summary: 'read-only probe',
    p_metadata: {},
  })
  console.log(`HTTP ${res.status} ${tag(res)}`)
}

console.log('')
console.log('--- record_sign_in repeated call (must not write without a session) ---')
{
  const res = await req('POST', '/rest/v1/rpc/record_sign_in', {})
  console.log(`HTTP ${res.status} ${tag(res)}`)
}

console.log('')
console.log('--- signup endpoint exposure (no account is created) ---')
{
  // Deliberately invalid payload: proves whether the endpoint is reachable without creating a user.
  const res = await req('POST', '/auth/v1/signup', { email: 'not-an-email' })
  console.log(`HTTP ${res.status} ${tag(res)}`)
}

import { readFileSync } from 'node:fs'

const sql = readFileSync(
  'supabase/migrations/20261124090000_phase1_foundation.sql',
  'utf8',
)

// Split into function blocks by locating each "create or replace function" up to its closing $$;
const blocks = []
const re = /create or replace function ([\w.]+)\s*\([^)]*\)[\s\S]*?\n\$\$;/gi
let match
while ((match = re.exec(sql))) {
  const block = match[0]
  blocks.push({
    name: match[1],
    definer: /security definer/i.test(block),
    invoker: /security invoker/i.test(block),
    fixedPath: /set search_path\s*=\s*''/i.test(block),
    returns: (block.match(/returns\s+([\w."\s]+?)\n/i) ?? [])[1]?.trim(),
    grants: /grant execute/i.test(block),
  })
}

console.log('FUNCTION SECURITY AUDIT')
for (const b of blocks) {
  console.log(
    `${b.name.padEnd(34)} ${b.definer ? 'DEFINER' : b.invoker ? 'INVOKER' : '?'}  search_path_fixed=${b.fixedPath}  returns=${b.returns ?? '?'}`,
  )
}

console.log('')
console.log(
  'definer functions missing fixed search_path:',
  blocks.filter((b) => b.definer && !b.fixedPath).map((b) => b.name),
)

// Exact policy target check (ignoring comments)
const policyTargets = [...sql.matchAll(/create policy[\s\S]*?\n\s*to (\w+)/gi)].map((m) => m[1])
console.log('policy targets (actual):', policyTargets)

const anonPolicy = /create policy[\s\S]*?\n\s*to anon\b/i.test(sql)
const publicPolicy = /create policy[\s\S]*?\n\s*to public\b/i.test(sql)
console.log('any policy granted to anon:', anonPolicy)
console.log('any policy granted to public:', publicPolicy)

// Ensure no write policy exists anywhere
const writePolicies = [
  ...sql.matchAll(/create policy "([^"]+)"[\s\S]*?\nfor (insert|update|delete|all)/gi),
].map((m) => `${m[1]}:${m[2]}`)
console.log('write policies (should be empty):', writePolicies)

// Ensure RLS is enabled on each table before policies are created
const rlsTables = [...sql.matchAll(/alter table (public\.\w+)\s+enable row level security/gi)].map(
  (m) => m[1],
)
console.log('RLS enabled on:', rlsTables)

// Confirm the anon role is explicitly stripped on all three tables
const anonRevokes = [...sql.matchAll(/revoke all on table (public\.\w+) from anon/gi)].map(
  (m) => m[1],
)
console.log('anon revoked on:', anonRevokes)

// Confirm authenticated only receives SELECT
const authGrants = [...sql.matchAll(/grant (\w+) on table (public\.\w+) to authenticated/gi)].map(
  (m) => `${m[1]} -> ${m[2]}`,
)
console.log('authenticated table grants:', authGrants)

import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync(new URL('./.env', import.meta.url), 'utf8')
    .split(/\r?\n/)
    .filter((line) => line && !line.startsWith('#') && line.includes('='))
    .map((line) => {
      const i = line.indexOf('=')
      return [line.slice(0, i).trim(), line.slice(i + 1).trim()]
    }),
)

const base = env.VITE_SUPABASE_URL
const key = env.VITE_SUPABASE_ANON_KEY
const headers = { apikey: key, Authorization: `Bearer ${key}` }

async function probe(query) {
  const res = await fetch(`${base}/rest/v1/profiles?${query}`, { headers })
  const text = await res.text()
  let body
  try {
    body = JSON.parse(text)
  } catch {
    body = text
  }
  const b = Array.isArray(body) ? `rows=${body.length}` : `${body.code ?? ''} ${body.message ?? ''}`
  return `HTTP ${res.status} ${String(b).slice(0, 110)}`
}

console.log('role=eq.administrator     ', await probe('select=id&role=eq.administrator&limit=1'))
