console.log('role=eq.trace_invalid     ', await probe('select=id&role=eq.trace_invalid&limit=1'))
console.log('is_active=eq.true         ', await probe('select=id&is_active=eq.true&limit=1'))
console.log('order=created_at.desc     ', await probe('select=id&order=created_at.desc&limit=1'))

